<template><view class="story-carousel"><swiper class="story-swiper" :current="current" :autoplay="false" :circular="true" :duration="450" @change="change"><swiper-item v-for="(s,i) in slides" :key="s.title"><view :class="['story-slide','slide-'+i]"><image class="slide-landscape" src="/static/青绿山水.jpg" mode="aspectFill"/><image v-if="s.image" class="slide-portrait" :src="s.image" mode="aspectFit"/><view class="slide-copy"><text class="eyebrow">{{s.label}}</text><text class="slide-title">{{s.title}}<text class="title-line">{{s.subtitle}}</text></text><text class="slide-description">{{s.description}}</text><button class="primary slide-action" @tap="open(i)">{{s.action}} <text>↗</text></button><text class="slide-note">{{s.note}}</text></view><text class="slide-seal">{{s.seal}}</text></view></swiper-item></swiper><view class="slide-navigation"><view class="slide-tabs"><button v-for="(s,i) in slides" :key="s.tab" :class="{selected:current===i}" :aria-label="'切换到'+s.tab" @tap="current=i"><text>0{{i+1}}</text>{{s.tab}}</button></view><view class="slide-arrows"><button aria-label="上一张" @tap="move(-1)">‹</button><text>0{{current+1}} / 03</text><button aria-label="下一张" @tap="move(1)">›</button></view></view></view></template>
<script setup>
import {ref} from 'vue';import {go} from '../lib/navigation.js';
const current=ref(0),slides=[
{tab:'山河总览',label:'山河有迹 · 深度人物专题',title:'循山河之迹',subtitle:'读时代之人',description:'从一位人物开始，沿着年代与史料，走近历史中的真实片段。',action:'走近人物',note:'山水装饰意象 · 非历史地理示意',seal:'循迹读人'},
{tab:'人物档案',label:'人物专题 / 瞿秋白',title:'从一个名字',subtitle:'走进一段人生',description:'沿着生平片段与资料出处，阅读瞿秋白的时代足迹。',action:'阅读档案',note:'人物图为艺术化IP，非历史照片',seal:'以史为据',image:'/static/人物形象/瞿秋白.png'},
{tab:'沉浸故事',label:'互动叙事 / 第一幕',title:'窗边的微光',subtitle:'倾听她们的盼望',description:'环顾牢房，点击窗边热点，在人物对话中展开故事。',action:'进入故事',note:'原创文学主题场景 · 非历史现场复原',seal:'走进故事',image:'/static/人物形象/江竹筠.png'}];
function change(e){current.value=e.detail.current}function move(d){current.value=(current.value+d+slides.length)%slides.length}
function open(i){if(i===0)return go('people');if(i===1)return go('person',{id:'P009'});
// #ifdef H5
window.location.assign('/panorama/jiang/第一幕动态版.html');
// #endif
// #ifndef H5
go('panorama',{story:'jiang'});
// #endif
}
</script>
<style>
.story-carousel{border:1px solid #e4d3b6;border-radius:18px;overflow:hidden;background:#fbf5e9;margin-top:20px;box-shadow:0 10px 28px #62432208}.story-swiper{height:420px}.story-slide{position:relative;height:100%;overflow:hidden}.slide-landscape{position:absolute;inset:0;width:100%;height:100%}.slide-copy{position:relative;padding:42px 44px;width:57%;z-index:2}.slide-copy .eyebrow{font-size:10px;letter-spacing:.16em;color:#92744f}.slide-title{display:block;font-family:STSong,SimSun,serif;font-size:43px;line-height:1.5;letter-spacing:.08em;color:#354d43;margin:18px 0}.slide-description{display:block;font-size:13px;line-height:1.95;color:#7e6d57;max-width:350px}.slide-action{display:flex;justify-content:space-between;width:150px;min-height:44px;padding:10px 16px;font-size:13px;margin:22px 0 0}.slide-note{display:block;font-size:10px;color:#9c8768;margin-top:17px}.slide-seal{position:absolute;right:28px;top:32px;writing-mode:vertical-rl;border:1px solid #aa645660;padding:12px 6px;color:#982b28;font-family:STSong,SimSun,serif;letter-spacing:.2em;font-size:14px}.slide-portrait{position:absolute;right:8%;bottom:0;width:36%;height:85%;z-index:1}.slide-1 .slide-landscape,.slide-2 .slide-landscape{opacity:.45}.slide-navigation{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e6d7bf;background:#fffaf1;padding:10px 20px;gap:12px}.slide-tabs{display:flex;gap:10px}.slide-tabs button{display:flex;gap:7px;align-items:center;justify-content:center;padding:8px 13px;font-size:12px;color:#8a775f;min-height:40px;border-radius:8px}.slide-tabs button text{font-family:Georgia,serif;font-size:10px;opacity:.7}.slide-tabs button.selected{background:#f0e4d1;color:#982b28}.slide-arrows{display:flex;align-items:center;gap:12px;color:#8a775f}.slide-arrows>text{font-size:10px;white-space:nowrap}.slide-arrows button{width:38px;min-height:38px;border:1px solid #e4d3b6;border-radius:50%;font-size:23px;line-height:1;color:#982b28}@media(max-width:650px){.story-swiper{height:430px}.slide-copy{padding:27px 22px;width:100%}.slide-title{font-size:29px;margin:16px 0}.slide-description{font-size:12px;max-width:75%}.slide-note{font-size:9px;max-width:70%;line-height:1.7}.slide-action{width:135px;font-size:12px;margin-top:18px}.slide-portrait{right:-5%;width:52%;height:45%;opacity:.9}.slide-1 .slide-copy,.slide-2 .slide-copy{padding-bottom:130px}.slide-seal{right:13px;top:25px;font-size:11px;padding:8px 4px}.slide-navigation{padding:8px;gap:3px}.slide-tabs{gap:2px}.slide-tabs button{font-size:10px;padding:7px 8px;gap:4px}.slide-arrows{gap:5px}.slide-arrows button{width:30px;min-height:34px}.slide-arrows>text{display:none}}
</style>
